import openpyxl, re
wb = openpyxl.load_workbook('sheetpedia_batch1_0031_incorrect_index-match_5033_input.xlsx', data_only=False)
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v = cell.value
            if isinstance(v, str) and 'INDEX' in v:
                # find MATCH(...,...,type)
                for m in re.finditer(r'MATCH\(([^,]+),([^,]+),([^)]+)\)', v):
                    if m.group(3).strip() != '0':
                        print(ws.title, cell.coordinate, '| type=', m.group(3).strip(), '|', v)
